--
-- Table structure for table `e_care_appointment`
--

DROP TABLE IF EXISTS `e_care_appointment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_care_appointment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `appointment_no` varchar(50) NOT NULL COMMENT '预约编号',
  `appointer_id` bigint DEFAULT NULL COMMENT '预约人ID（通常为家属）',
  `appointer_name` varchar(50) DEFAULT NULL COMMENT '预约人姓名',
  `appointer_phone` varchar(20) DEFAULT NULL COMMENT '预约人联系电话',
  `appointer_relation` varchar(50) DEFAULT NULL COMMENT '预约人与长者关系（子女/配偶/本人等）',
  `resident_id` int DEFAULT NULL COMMENT '意向入住长者ID（关联 e_resident.id，新客可空）',
  `resident_name` varchar(50) DEFAULT NULL COMMENT '意向入住长者姓名',
  `gender_required` tinyint(1) DEFAULT '0' COMMENT '房型性别偏好：0-不限 1-男 2-女',
  `bed_count` int DEFAULT '1' COMMENT '意向床位数',
  `care_level_demand` enum('自理','半自理','失能') DEFAULT '自理' COMMENT '意向护理等级',
  `building_pref` varchar(100) DEFAULT NULL COMMENT '意向楼栋/康养区',
  `appointment_date` date NOT NULL COMMENT '预约到访/入住日期',
  `estimated_days` int NOT NULL COMMENT '预计住养天数',
  `combo_id` bigint DEFAULT NULL COMMENT '选择的康养套餐ID',
  `combo_name` varchar(415) DEFAULT NULL COMMENT '康养套餐名称',
  `daily_price` decimal(10,2) DEFAULT NULL COMMENT '日单价',
  `estimated_fee` decimal(10,2) DEFAULT NULL COMMENT '预计费用',
  `deposit_amount` decimal(10,2) DEFAULT '0.00' COMMENT '定金金额',
  `status` tinyint(1) DEFAULT '0' COMMENT '状态（0-待确认 1-已确认 2-已取消 3-已到访参观 4-已登记入住 5-已过期）',
  `special_needs` varchar(500) DEFAULT NULL COMMENT '特殊需求（单人间/就近医院/清真餐等）',
  `remarks` varchar(500) DEFAULT NULL COMMENT '备注',
  `is_vip` tinyint(1) DEFAULT '0' COMMENT '是否会员',
  `is_urgent` tinyint(1) DEFAULT '0' COMMENT '是否加急',
  `member_id` bigint DEFAULT NULL COMMENT '关联系统用户ID',
  `cover_image` varchar(500) DEFAULT NULL COMMENT '封面图',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_appointment_no` (`appointment_no`),
  KEY `idx_appointer_id` (`appointer_id`),
  KEY `idx_resident_id` (`resident_id`),
  KEY `idx_status` (`status`),
  KEY `idx_appointment_date` (`appointment_date`)
) ENGINE=InnoDB AUTO_INCREMENT=623 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='住养预约表（status=4时生成 e_care_checkin 并回填 appointment_id）';
/*!40101 SET character_set_client = @saved_cs_client */;

