DROP TABLE IF EXISTS `e_care_bed`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_care_bed` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `building_id` bigint NOT NULL COMMENT '楼栋ID（e_care_building.id）',
  `floor_id` bigint NOT NULL COMMENT '楼层ID（e_care_floor_plan.id）',
  `room_id` bigint NOT NULL COMMENT '房间ID（e_care_room.id）',
  `bed_no` varchar(50) NOT NULL COMMENT '床位编号（如：201-1）',
  `bed_name` varchar(100) DEFAULT NULL COMMENT '床位名称',
  `bed_type` tinyint(1) DEFAULT '1' COMMENT '床位类型：1-普通床 2-护理床 3-康复床',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态 0-禁用 1-空闲 2-占用 3-预订 4-维修 5-清洁',
  `cur_resident_id` bigint DEFAULT NULL COMMENT '当前入住长者ID',
  `cur_resident_name` varchar(50) DEFAULT NULL COMMENT '当前入住长者姓名',
  `checkin_id` bigint DEFAULT NULL COMMENT '当前入住登记ID（e_care_checkin.id）',
  `checkin_time` datetime DEFAULT NULL COMMENT '入住时间',
  `daily_price` decimal(10,2) DEFAULT '80.00' COMMENT '床位日单价（元）',
  `use_num` int DEFAULT '0' COMMENT '使用次数',
  `remark` varchar(450) DEFAULT NULL COMMENT '备注',
  `sort_order` int DEFAULT '100' COMMENT '排序',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '删除标志：0-正常 1-已删除',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bed_no` (`room_id`,`bed_no`,`is_delete`),
  KEY `idx_room_id` (`room_id`),
  KEY `idx_status` (`status`),
  KEY `idx_cur_resident_id` (`cur_resident_id`),
  KEY `idx_checkin_id` (`checkin_id`)
) ENGINE=InnoDB AUTO_INCREMENT=383 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='床位表';
/*!40101 SET character_set_client = @saved_cs_client */;

