--
-- Table structure for table `e_care_building`
--

DROP TABLE IF EXISTS `e_care_building`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_care_building` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `building_no` varchar(50) NOT NULL COMMENT '楼栋编号',
  `building_name` varchar(100) DEFAULT NULL COMMENT '楼栋名称（如：银杏楼/养护区A栋）',
  `building_type` tinyint(1) DEFAULT '1' COMMENT '楼栋类型：1-独立楼栋 2-楼层分区',
  `total_floors` int DEFAULT '1' COMMENT '总楼层数',
  `usage_type` varchar(50) DEFAULT NULL COMMENT '用途分区（养护区/自理区/康复区/认知照护区）',
  `manager_id` bigint DEFAULT NULL COMMENT '楼栋负责人ID（员工）',
  `manager_name` varchar(50) DEFAULT NULL COMMENT '楼栋负责人姓名',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态（0-禁用 1-启用）',
  `sort_order` int DEFAULT '100' COMMENT '排序',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '删除标志：0-正常 1-已删除',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_building_no` (`building_no`,`is_delete`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='楼栋表';
/*!40101 SET character_set_client = @saved_cs_client */;

