--
-- Table structure for table `e_care_charge_combo`
--

DROP TABLE IF EXISTS `e_care_charge_combo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_care_charge_combo` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `combo_name` varchar(100) NOT NULL COMMENT '康养套餐名称',
  `gender_required` tinyint(1) DEFAULT '0' COMMENT '房型性别要求：0-不限 1-男 2-女',
  `description` varchar(500) DEFAULT NULL COMMENT '套餐说明',
  `status` tinyint(1) DEFAULT '1' COMMENT '是否启用（0-禁用 1-启用）',
  `recommended` tinyint(1) DEFAULT '0' COMMENT '是否推荐（0-否 1-是）',
  `year_price` decimal(10,2) DEFAULT '0.00' COMMENT '年费价格（元/年）',
  `month_price` decimal(10,2) DEFAULT '0.00' COMMENT '月费价格（元/月）',
  `day_price` decimal(10,2) DEFAULT '0.00' COMMENT '日费价格（元/天）',
  `charge_cycle` tinyint DEFAULT '2' COMMENT '计费周期：0-按年 1-按月 2-按天',
  `room_type` varchar(30) DEFAULT NULL COMMENT '房间类型',
  `deposit_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '押金金额（元）',
  `total_price` decimal(10,2) DEFAULT '80.00' COMMENT '优惠总价格（元）',
  `total_org_price` decimal(10,2) DEFAULT '0.00' COMMENT '总原价（元）',
  `has_camera` tinyint(1) DEFAULT '1' COMMENT '是否有监控：0-无 1-有',
  `has_air_conditioner` tinyint(1) DEFAULT '1' COMMENT '是否有空调：0-无 1-有',
  `water_type` tinyint(1) DEFAULT '1' COMMENT '饮水服务：0-无 1-人工送水 2-直饮水',
  `feeding_type` tinyint(1) DEFAULT '1' COMMENT '用餐服务：0-自助餐 1-送餐到房 2-食堂就餐',
  `has_nurse_call` tinyint(1) DEFAULT '1' COMMENT '是否有床头呼叫器：0-无 1-有',
  `has_emergency_bell` tinyint(1) DEFAULT '1' COMMENT '是否有紧急按钮：0-无 1-有',
  `room_mode` tinyint(1) DEFAULT '1' COMMENT '房型模式：0-多人间 1-单人间',
  `environment_images` varchar(2000) DEFAULT NULL COMMENT '环境图片（JSON数组）',
  `book_num` int DEFAULT '0' COMMENT '预约次数',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `charge_kind` int DEFAULT NULL COMMENT '收费类型：0 住养收费 1 服务收费',
  `popularity` int DEFAULT '0' COMMENT '人气值（选择次数）',
  `duration` int DEFAULT '0' COMMENT '预计时长（分钟，服务类套餐适用）',
  `suitable_for` varchar(450) DEFAULT NULL COMMENT '适用护理等级列表（JSON数组）',
  `room_area` varchar(45) DEFAULT NULL COMMENT '房间面积（如：25㎡）',
  `max_residents` int DEFAULT '1' COMMENT '可住长者数',
  `cover_image` varchar(450) DEFAULT NULL COMMENT '封面图',
  PRIMARY KEY (`id`),
  KEY `idx_gender_required` (`gender_required`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='康养收费套餐表';
/*!40101 SET character_set_client = @saved_cs_client */;

