DROP TABLE IF EXISTS `e_care_checkin`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_care_checkin` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `checkin_no` varchar(50) NOT NULL COMMENT '入住登记单号',
  `appointment_id` bigint DEFAULT NULL COMMENT '关联预约ID（e_care_appointment.id）',
  `resident_id` int NOT NULL COMMENT '主入住长者ID（关联 e_resident.id）',
  `resident_no` varchar(50) DEFAULT NULL COMMENT '长者编号',
  `resident_name` varchar(50) NOT NULL COMMENT '长者姓名',
  `contact_name` varchar(50) DEFAULT NULL COMMENT '紧急联系人/家属姓名',
  `contact_phone` varchar(20) DEFAULT NULL COMMENT '紧急联系人电话',
  `contact_phone_backup` varchar(20) DEFAULT NULL COMMENT '备用电话',
  `checkin_date` date NOT NULL COMMENT '入住日期',
  `checkout_date` date DEFAULT NULL COMMENT '预计退住日期',
  `actual_checkout_date` date DEFAULT NULL COMMENT '实际退住日期',
  `actual_days` int DEFAULT '0' COMMENT '实际住养天数',
  `resident_count` int DEFAULT '1' COMMENT '已废弃：一人一单恒为1',
  `building_id` bigint DEFAULT NULL COMMENT '楼栋ID（冗余主床位所在楼栋）',
  `room_id` bigint DEFAULT NULL COMMENT '房间ID（冗余主床位所在房间）',
  `bed_id` bigint DEFAULT NULL COMMENT '主床位ID（关联 e_care_bed.id）',
  `combo_id` bigint DEFAULT NULL COMMENT '康养套餐ID',
  `total_deposit` decimal(10,2) DEFAULT '0.00' COMMENT '押金合计（=deposit）',
  `settled` tinyint(1) DEFAULT '0' COMMENT '是否已结算（0-否 1-是）',
  `settlement_id` bigint DEFAULT NULL COMMENT '结算单ID（e_care_settlement.id）',
  `operator_name` varchar(50) DEFAULT NULL COMMENT '登记人员',
  `remarks` varchar(500) DEFAULT NULL COMMENT '备注',
  `special_needs` varchar(450) DEFAULT NULL COMMENT '特殊照护需求',
  `total_deposit_pay_state` int DEFAULT NULL COMMENT '押金支付状态',
  `total_deposit_pay_money` decimal(10,2) DEFAULT NULL COMMENT '押金支付金额',
  `total_deposit_refund_time` datetime DEFAULT NULL COMMENT '押金退还时间',
  `total_deposit_payment_method` varchar(45) DEFAULT NULL COMMENT '押金支付方式',
  `settled_discount` decimal(10,2) DEFAULT NULL COMMENT '优惠金额',
  `settled_final_amount` decimal(10,2) DEFAULT NULL COMMENT '应收/应退金额',
  `settled_actual_payment` decimal(10,2) DEFAULT NULL COMMENT '实收金额',
  `settled_payment_method` varchar(45) DEFAULT NULL COMMENT '支付方式',
  `handler_id` bigint DEFAULT NULL COMMENT '责任员工ID（健康管家）',
  `member_id` bigint DEFAULT NULL COMMENT '关联系统用户ID',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `is_delete` tinyint(1) DEFAULT '0' COMMENT '删除标志',
  `gender` tinyint(1) DEFAULT '0' COMMENT '性别：0-未知 1-男 2-女',
  `birth_date` date DEFAULT NULL COMMENT '出生日期',
  `id_card` varchar(28) DEFAULT NULL COMMENT '身份证号',
  `phone` varchar(20) DEFAULT NULL COMMENT '长者联系电话',
  `care_level` varchar(20) DEFAULT NULL COMMENT '护理等级（自理/半自理/失能）',
  `mental_state` varchar(20) DEFAULT NULL COMMENT '精神状态（GOOD-良好 NORMAL-一般 POOR-差）',
  `consciousness` varchar(20) DEFAULT NULL COMMENT '意识状态（CLEAR-清醒 DROWSY-嗜睡 CONFUSED-意识模糊）',
  `temperature` decimal(4,1) DEFAULT NULL COMMENT '体温(℃)',
  `pulse` int DEFAULT NULL COMMENT '脉搏(次/分)',
  `blood_pressure_high` int DEFAULT NULL COMMENT '收缩压(mmHg)',
  `blood_pressure_low` int DEFAULT NULL COMMENT '舒张压(mmHg)',
  `blood_oxygen` int DEFAULT NULL COMMENT '血氧饱和度(%)',
  `vision` varchar(20) DEFAULT NULL COMMENT '视力（NORMAL-正常 DECLINED-下降 IMPAIRED-障碍）',
  `hearing` varchar(20) DEFAULT NULL COMMENT '听力（NORMAL-正常 DECLINED-下降 IMPAIRED-障碍）',
  `cognition` varchar(20) DEFAULT NULL COMMENT '认知筛查（NORMAL-正常 SUSPECTED-疑似失智 CONFIRMED-确诊失智）',
  `fall_risk` varchar(10) DEFAULT NULL COMMENT '跌倒风险（LOW-低 MEDIUM-中 HIGH-高）',
  `pressure_sore` varchar(20) DEFAULT NULL COMMENT '压疮（NONE-无 I_II-I~II度 III_IV-III~IV度）',
  `self_care_ability` varchar(20) DEFAULT NULL COMMENT '自理能力（FULL-能 PARTIAL-部分 NONE-完全不能）',
  `chronic_diseases` varchar(500) DEFAULT NULL COMMENT '慢性疾病',
  `medications` varchar(500) DEFAULT NULL COMMENT '在服药物',
  `allergies` varchar(200) DEFAULT NULL COMMENT '过敏史（药物/食物）',
  `diet_type` varchar(30) DEFAULT NULL COMMENT '膳食类型',
  `elimination` varchar(200) DEFAULT NULL COMMENT '大小便情况',
  `checkin_photos` varchar(1045) DEFAULT NULL COMMENT '入住近照（逗号分隔）',
  `brought_items` varchar(405) DEFAULT NULL COMMENT '自带个人物品',
  `brought_photos` varchar(1045) DEFAULT NULL COMMENT '物品照片',
  `room_name` varchar(50) DEFAULT NULL COMMENT '房间名称（快照）',
  `bed_no` varchar(50) DEFAULT NULL COMMENT '床位编号（快照）',
  `charge_cycle` tinyint(1) DEFAULT '2' COMMENT '套餐计费周期快照：0-按年 1-按月 2-按天',
  `charge_num` int DEFAULT NULL COMMENT '计划时长数量（配合 charge_cycle 表示多少年/月/天）',
  `period_price` decimal(10,2) DEFAULT NULL COMMENT '周期单价快照（charge_cycle 对应原价）',
  `combo_year_price` decimal(10,2) DEFAULT NULL COMMENT '套餐年价快照（元/年，按实际时长逐段计费）',
  `combo_month_price` decimal(10,2) DEFAULT NULL COMMENT '套餐月价快照（元/月，按实际时长逐段计费）',
  `combo_day_price` decimal(10,2) DEFAULT NULL COMMENT '套餐日价快照（元/天，按实际时长逐段计费）',
  `deposit` decimal(10,2) DEFAULT NULL COMMENT '本单押金',
  `checkin_status` tinyint(1) DEFAULT '0' COMMENT '入住状态：0-登记中 1-待入住 2-康养中 3-已退住 9-已拒收',
  `checkout_status` tinyint(1) DEFAULT '0' COMMENT '退住交接状态：0-未开始 1-交接中 2-已完成',
  `checkout_no` varchar(50) DEFAULT NULL COMMENT '退住交接单号',
  `checkout_photos` varchar(1045) DEFAULT NULL COMMENT '退住时长者近照',
  `appearance_changes` varchar(405) DEFAULT NULL COMMENT '身体状况变化说明',
  `health_change_desc` tinyint(1) DEFAULT '0' COMMENT '身体状况变化结果（0-正常 1-有变化）',
  `care_summary` tinyint(1) DEFAULT '0' COMMENT '个人卫生状态（0-整洁 1-一般 2-需清洁）',
  `items_status` tinyint(1) DEFAULT '0' COMMENT '个人物品状态（0-完好 1-有损耗 2-有损坏）',
  `items_confirmed` int DEFAULT '0' COMMENT '物品交接确认（0-未确认 1-已确认）',
  `items_remark` varchar(145) DEFAULT NULL COMMENT '物品备注',
  `returned_items` varchar(450) DEFAULT NULL COMMENT '归还/转交家属物品',
  `customer_feedback` varchar(145) DEFAULT NULL COMMENT '长者/家属反馈',
  `customer_satisfaction` tinyint(1) DEFAULT NULL COMMENT '满意度评分（1-5）',
  `suggestions` varchar(145) DEFAULT NULL COMMENT '后续照料建议',
  `health_reminder` varchar(145) DEFAULT NULL COMMENT '健康提醒事项',
  `performance` varchar(145) DEFAULT NULL COMMENT '在住适应情况',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_checkin_no` (`checkin_no`),
  KEY `idx_resident_id` (`resident_id`),
  KEY `idx_checkin_date` (`checkin_date`),
  KEY `idx_handler_id` (`handler_id`),
  KEY `idx_room_id` (`room_id`),
  KEY `idx_bed_id` (`bed_id`),
  KEY `idx_checkin_status` (`checkin_status`)
) ENGINE=InnoDB AUTO_INCREMENT=424 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='入住登记表';
/*!40101 SET character_set_client = @saved_cs_client */;

