DROP TABLE IF EXISTS `e_care_checkin_fee_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_care_checkin_fee_item` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `checkin_id` bigint NOT NULL COMMENT '入住登记ID（e_care_checkin.id）',
  `item_id` bigint NOT NULL COMMENT '费用项ID',
  `item_name` varchar(100) NOT NULL COMMENT '费用项名称',
  `item_type` varchar(30) NOT NULL COMMENT '费用项类型',
  `charge_mode` tinyint(1) NOT NULL COMMENT '计费方式（0-按天 1-按次 2-固定 3-按重 4-按年 5-按月）',
  `unit_price` decimal(10,2) NOT NULL COMMENT '单价',
  `quantity` int DEFAULT '1' COMMENT '数量',
  `is_original` tinyint(1) DEFAULT '0' COMMENT '是否原套餐项目',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `is_delete` int DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_item_id` (`item_id`),
  KEY `idx_checkin_id` (`checkin_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1115 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='入住长者费用项表';
