CREATE TABLE `e_care_daily_arrangement` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `kind` int NOT NULL COMMENT '安排类型:0 常规安排 1 特殊时期安排',
  `week` int NOT NULL DEFAULT '0' COMMENT '安排类型:1~7 周一到星期日 0 特殊时期安排',
  `arrangement_date` date DEFAULT NULL COMMENT '安排日期',
  `arrangement_time` time NOT NULL COMMENT '安排时间',
  `content` varchar(255) NOT NULL COMMENT '安排内容',
