--
-- Table structure for table `e_care_employee`
--

DROP TABLE IF EXISTS `e_care_employee`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_care_employee` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '员工ID',
  `employee_no` varchar(50) NOT NULL COMMENT '员工编号',
  `name` varchar(50) NOT NULL COMMENT '姓名',
  `gender` tinyint(1) DEFAULT '0' COMMENT '性别：0-未知，1-男，2-女',
  `id_card` varchar(18) DEFAULT NULL COMMENT '身份证号',
  `birthday` date DEFAULT NULL COMMENT '出生日期',
  `phone` varchar(20) NOT NULL COMMENT '联系电话',
  `emergency_contact` varchar(50) DEFAULT NULL COMMENT '紧急联系人',
  `emergency_phone` varchar(20) DEFAULT NULL COMMENT '紧急联系电话',
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像URL',
  `level` int DEFAULT '2' COMMENT '等级：1-初级，2-中级，3-高级，4-特级',
  `position` varchar(50) DEFAULT NULL COMMENT '职位：护理员、照护师、营养师、护士长、店长等',
  `skills` varchar(1000) DEFAULT NULL COMMENT '专长技能列表（JSON数组）',
  `certification` varchar(500) DEFAULT NULL COMMENT '资质证书（JSON数组）',
  `hire_date` date DEFAULT NULL COMMENT '入职日期',
  `leave_date` date DEFAULT NULL COMMENT '离职日期',
  `employee_status` tinyint(1) DEFAULT '1' COMMENT '员工状态：0-离职，1-在职，2-试用期，3-实习',
  `is_care` int DEFAULT '0' COMMENT '是否康养护理服务：0-否，1-是',
  `is_rehab` int DEFAULT '1' COMMENT '是否康复服务：0-否，1-是',
  `is_sales` int DEFAULT '0' COMMENT '是否商品销售：0-否，1-是',
  `max_daily` int DEFAULT '8' COMMENT '每日最大服务量',
  `enabled` tinyint(1) DEFAULT '1' COMMENT '启用状态：0-禁用，1-启用',
  `user_id` bigint DEFAULT NULL COMMENT '关联系统用户ID（用于登录）',
  `bank_name` varchar(100) DEFAULT NULL COMMENT '开户银行',
  `bank_account` varchar(50) DEFAULT NULL COMMENT '银行账号（用于发放工资）',
  `address` varchar(500) DEFAULT NULL COMMENT '家庭住址',
  `wechat` varchar(50) DEFAULT NULL COMMENT '微信号',
  `email` varchar(100) DEFAULT NULL COMMENT '邮箱',
  `base_salary` decimal(10,2) DEFAULT '0.00' COMMENT '基本工资',
  `commission_rate` decimal(5,2) DEFAULT '0.00' COMMENT '默认提成比例（%）',
  `total_orders` int DEFAULT '0' COMMENT '累计完成单数',
  `total_amount` decimal(10,2) DEFAULT '0.00' COMMENT '累计完成金额',
  `rating` decimal(3,2) DEFAULT '5.00' COMMENT '平均评分（5分制）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `is_delete` tinyint(1) DEFAULT '0' COMMENT '删除标志：0-正常，1-删除',
  `hire_file` varchar(1045) DEFAULT NULL,
  `hire_referee` varchar(45) DEFAULT NULL COMMENT '推荐人',
  `hire_referee_reason` varchar(450) DEFAULT NULL COMMENT '推荐理由',
  `leave_file` varchar(1045) DEFAULT NULL,
  `leave_reason` varchar(450) DEFAULT NULL COMMENT '离职原因',
  `wash_state` int DEFAULT '1' COMMENT '是否启用 1 是 0 否',
  `role_ids` varchar(500) DEFAULT NULL COMMENT '已分配角色ID(逗号分隔,来源sys_user_role的冗余快照,便于员工列表直接展示权限)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_employee_no` (`employee_no`),
  KEY `idx_level` (`level`),
  KEY `idx_enabled` (`enabled`),
  KEY `idx_employee_status` (`employee_status`),
  KEY `idx_phone` (`phone`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_store_phone` (`phone`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='员工信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

