DROP TABLE IF EXISTS `e_care_employee_schedule`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_care_employee_schedule` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '排班ID',
  `employee_id` bigint NOT NULL COMMENT '员工ID',
  `schedule_date` date NOT NULL COMMENT '排班日期',
  `time_slot` varchar(20) NOT NULL DEFAULT '08:00' COMMENT '时间段：09:00, 10:00等',
  `slot_status` int DEFAULT '0' COMMENT '时段状态：0-可约, 1-已约, 2-休息',
  `appointment_id` bigint DEFAULT NULL COMMENT '关联预约ID（已约时）',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_delete` int DEFAULT '0',
  `schedule_type` int DEFAULT '0' COMMENT '排班类型：0 小时排班 1 值班',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_employee_date_slot` (`employee_id`,`schedule_date`,`time_slot`,`is_delete`),
  KEY `idx_employee_id` (`employee_id`),
  KEY `idx_schedule_date` (`schedule_date`),
  KEY `idx_slot_status` (`slot_status`)
) ENGINE=InnoDB AUTO_INCREMENT=129 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='护理排班表';
/*!40101 SET character_set_client = @saved_cs_client */;

