--
-- Table structure for table `e_care_fee_item`
--

DROP TABLE IF EXISTS `e_care_fee_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_care_fee_item` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `item_name` varchar(100) NOT NULL COMMENT '项目名称',
  `item_type` tinyint(1) DEFAULT '1' COMMENT '项目类型：0-基础(床位) 1-护理 2-餐饮 3-医疗 4-康复 5-增值 6-赔偿 7-其他',
  `charge_mode` tinyint(1) NOT NULL DEFAULT '0' COMMENT '计费方式（0-按天 1-按次 2-固定 3-按重 4-按年 5-按月）',
  `unit_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '单价',
  `status` tinyint(1) DEFAULT '1' COMMENT '是否启用（0-禁用 1-启用）',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `description` varchar(1045) DEFAULT NULL COMMENT '描述',
  `duration` int DEFAULT NULL COMMENT '预计时长（分钟）',
  `charge_kind` int DEFAULT '0' COMMENT '收费类型：0 住养收费 1 服务收费',
  PRIMARY KEY (`id`),
  KEY `idx_item_type` (`item_type`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='收费类目表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
