DROP TABLE IF EXISTS `e_care_floor_plan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_care_floor_plan` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `building_id` bigint NOT NULL COMMENT '楼栋ID（e_care_building.id）',
  `floor_no` int NOT NULL COMMENT '楼层号（地下层用负数）',
  `floor_name` varchar(50) DEFAULT NULL COMMENT '楼层名称（如：1F/护理一层）',
  `plan_images` varchar(2000) DEFAULT NULL COMMENT '楼层平面图（JSON数组）',
  `orientation` varchar(50) DEFAULT NULL COMMENT '主要朝向（南/北/东南等）',
  `has_elevator` tinyint(1) DEFAULT '0' COMMENT '是否有电梯：0-无 1-有',
  `area` decimal(10,2) DEFAULT NULL COMMENT '楼层面积（㎡）',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '删除标志：0-正常 1-已删除',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_building_floor` (`building_id`,`floor_no`,`is_delete`),
  KEY `idx_building_id` (`building_id`)
) ENGINE=InnoDB AUTO_INCREMENT=110 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='楼层表（含楼层平面布局）';
