--
-- Table structure for table `e_care_health_check_record`
--

DROP TABLE IF EXISTS `e_care_health_check_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_care_health_check_record` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `check_no` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检查编号',
  `checkin_id` bigint DEFAULT NULL COMMENT '入住登记ID（e_care_checkin.id）',
  `checkin_no` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '入住登记单号',
  `tenant_id` int DEFAULT '0' COMMENT '租户ID',
  `member_id` bigint DEFAULT NULL COMMENT '会员ID',
  `member_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '会员名称',
  `resident_id` bigint DEFAULT NULL COMMENT '长者ID，关联 e_resident.id',
  `resident_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '长者姓名',
  `check_type` tinyint DEFAULT '1' COMMENT '检查类型：1-入住评估 2-在住定期检查 3-退住评估 4-专项巡查',
  `check_stage` tinyint DEFAULT '1' COMMENT '检查阶段：1-入住前 2-在住 3-退住',
  `check_date` datetime DEFAULT NULL COMMENT '检查时间',
  `check_location` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检查地点',
  `health_status` tinyint DEFAULT '1' COMMENT '健康状态：1-健康 2-轻微疾病 3-严重疾病',
  `health_score` int DEFAULT '100' COMMENT '健康评分（0-100）',
  `check_items` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '检查项目详情（JSON）',
  `body_condition` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身体状况描述',
  `skin_condition` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '皮肤状况描述',
  `eye_condition` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '眼部状况描述',
  `ear_condition` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '耳部状况描述',
  `mouth_condition` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '口腔状况描述',
  `behavior_condition` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '行为状况描述',
  `disease_detected` tinyint DEFAULT '0' COMMENT '是否检测出疾病：0-否 1-是',
  `disease_type` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '疾病类型',
  `disease_description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '疾病描述',
  `treatment_needed` tinyint DEFAULT '0' COMMENT '是否需要治疗：0-否 1-是',
  `treatment_plan` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '治疗方案',
  `estimated_treatment_cost` decimal(10,2) DEFAULT '0.00' COMMENT '预估治疗费用',
  `check_user_id` bigint DEFAULT NULL COMMENT '检查人员ID',
  `check_user_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检查人员姓名',
  `check_user_type` tinyint DEFAULT '1' COMMENT '检查人员类型：1-机构员工 2-医生/护士 3-第三方评估师',
  `check_photos` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检查照片（JSON数组）',
  `check_videos` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检查视频（JSON数组）',
  `check_report_file` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检查报告文件',
  `check_conclusion` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检查结论',
  `check_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检查备注',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `is_delete` tinyint DEFAULT '0' COMMENT '是否删除：0-否 1-是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_check_no` (`check_no`),
  KEY `idx_checkin_id` (`checkin_id`),
  KEY `idx_checkin_no` (`checkin_no`),
  KEY `idx_member_store` (`member_id`),
  KEY `idx_check_type` (`check_type`),
  KEY `idx_check_stage` (`check_stage`),
  KEY `idx_health_status` (`health_status`),
  KEY `idx_check_date` (`check_date`),
  KEY `idx_create_at` (`create_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2064 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='长者健康检查记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

