DROP TABLE IF EXISTS `e_care_notice`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_care_notice` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `title` varchar(145) DEFAULT NULL COMMENT '标题',
  `content` text NOT NULL COMMENT '内容',
  `app_type` tinyint NOT NULL DEFAULT '0' COMMENT '应用类型',
  `app_id` bigint NOT NULL DEFAULT '0' COMMENT '应用ID',
  `tips_type` tinyint DEFAULT '0' COMMENT '分类: 0=系统 1=活动 2=交易',
  `worth` int NOT NULL DEFAULT '0' COMMENT '价值',
  `view_count` int DEFAULT '0' COMMENT '浏览次数',
  `reply_count` int NOT NULL DEFAULT '0' COMMENT '回复次数',
  `reply_member_name` varchar(45) DEFAULT NULL COMMENT '最后回复人',
  `reply_last_time` datetime DEFAULT NULL COMMENT '最后回复时间',
  `sequence` int DEFAULT '0' COMMENT '排序',
  `valid_start_date` datetime DEFAULT NULL COMMENT '有效时间起',
  `valid_end_date` datetime DEFAULT NULL COMMENT '有效时间止',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `state` tinyint NOT NULL DEFAULT '0' COMMENT '状态: 0=待处理 1=已处理 2=已关闭',
  `create_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_tips_type` (`tips_type`),
  KEY `idx_state` (`state`),
  KEY `idx_create_at` (`create_at`)
) ENGINE=InnoDB AUTO_INCREMENT=9009 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='店铺通知表';
