INSERT INTO `e_care_notice` VALUES (9001,'降温提醒：请及时添加衣物','<p>气象部门发布寒潮预警，院内已将夜间空调调至 24℃，请家属探视时为长者增添外套。</p>',1,0,0,0,3,0,NULL,NULL,1,'2026-10-20 08:00:00','2026-12-31 23:59:59','演示通知',1,'2026-10-20 09:30:00',NULL,0),(9002,'重阳节家属开放日报名开始','<p>10 月 24 日全天开放，包含健康义诊、手工课与食堂午餐体验，限 60 个家庭。</p>',2,3,1,0,185,2,'家属（演示）','2026-10-15 20:00:00',2,'2026-10-15 08:00:00','2026-12-31 23:59:59','演示通知',0,'2026-10-15 09:30:00',NULL,0),(9003,'结算单待确认提醒','<p>长者程立德的退住结算单已生成，请在 3 日内确认金额并完成支付。</p>',3,501,2,0,3,0,NULL,NULL,3,'2026-10-28 08:00:00','2026-12-31 23:59:59','演示通知',0,'2026-10-28 09:30:00',NULL,0),(9004,'每周三夜间维护窗口','<p>22:00-23:00 例行维护，小程序端可能短暂不可用，紧急情况请拨打一号线。</p>',1,0,0,0,3,1,'家属（演示）','2026-09-01 20:00:00',4,'2026-09-01 08:00:00','2026-12-31 23:59:59','演示通知',2,'2026-09-01 09:30:00',NULL,0),(9005,'银杏楼书画展作品征集','<p>面向全体住户征集书法与国画作品，入选作品将在一层活动室展出两周。</p>',2,5,1,0,129,1,'家属（演示）','2026-10-08 20:00:00',5,'2026-10-08 08:00:00','2026-12-31 23:59:59','演示通知',0,'2026-10-08 09:30:00',NULL,0),(9006,'会员卡充值到账通知','<p>您的会员卡充值已到账，赠送金额同步生效，可在小程序查看流水。</p>',3,801,2,0,3,1,'家属（演示）','2026-10-12 20:00:00',6,'2026-10-12 08:00:00','2026-12-31 23:59:59','演示通知',1,'2026-10-12 09:30:00',NULL,0),(9007,'认知专区防走失设备升级','<p>认知照护区已完成定位马甲升级，围栏告警延迟降至 5 秒以内。</p>',2,7,1,0,87,0,NULL,NULL,7,'2026-10-25 08:00:00','2026-12-31 23:59:59','演示通知',0,'2026-10-25 09:30:00',NULL,0),(9008,'食堂菜单意见收集','<p>十一月新菜单即将上线，欢迎家属与长者扫码填写口味与忌口需求。</p>',1,0,0,0,66,2,'家属（演示）','2026-10-22 20:00:00',8,'2026-10-22 08:00:00','2026-12-31 23:59:59','演示通知',0,'2026-10-22 09:30:00',NULL,0);
