  `audit_state` int DEFAULT '0' COMMENT '审核状态',
  `content_type` int DEFAULT '0' COMMENT '内容类型 0 默认 图文 1 存图片新闻',
  `title` varchar(150) NOT NULL COMMENT '主标题',
  `subtitle` varchar(1050) DEFAULT NULL COMMENT '副标题',
  `tags` varchar(1050) DEFAULT NULL COMMENT '副标题',
  `info_template` varchar(255) DEFAULT NULL COMMENT '信息模板',
  `description` longtext COMMENT '描述',
  `source` varchar(50) DEFAULT NULL COMMENT '来源名称',
  `source_url` varchar(550) DEFAULT NULL COMMENT '来源url',
  `author` varchar(50) DEFAULT NULL COMMENT '作者',
  `small_image` varchar(550) DEFAULT NULL COMMENT '小图',
  `video` varchar(550) DEFAULT NULL COMMENT '视频url',
  `video_name` varchar(255) DEFAULT NULL COMMENT '视频名称',
  `file` varchar(255) DEFAULT NULL COMMENT '文件url',
  `file_name` varchar(255) DEFAULT NULL COMMENT '文件名称',
  `file_length` bigint DEFAULT NULL COMMENT '文档长度',
  `is_allow_comment` char(1) DEFAULT NULL COMMENT '是否允许评论',
  `create_at` datetime DEFAULT NULL COMMENT '创建时间',
  `update_at` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `title` (`title`),
  KEY `publish_date` (`publish_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='企业公报';
