--
-- Table structure for table `e_care_room`
--

DROP TABLE IF EXISTS `e_care_room`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_care_room` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `building_id` bigint NOT NULL COMMENT '楼栋ID（e_care_building.id）',
  `floor_id` bigint NOT NULL COMMENT '楼层ID（e_care_floor_plan.id）',
  `room_no` varchar(50) NOT NULL COMMENT '房间编号（如：201）',
  `room_name` varchar(100) DEFAULT NULL COMMENT '房间名称',
  `room_type` tinyint DEFAULT NULL COMMENT '房型：1单人间 2双人间 3多人间 4夫妻房',
  `room_level` tinyint DEFAULT NULL COMMENT '房间等级：1普通 2高级 3豪华 4豪华+',
  `gender_type` tinyint(1) DEFAULT '0' COMMENT '房间性别要求：0-不限 1-男 2-女',
  `bed_count` int NOT NULL DEFAULT '1' COMMENT '床位总数',
  `occupied_count` int DEFAULT '0' COMMENT '当前入住人数',
  `orientation` varchar(50) DEFAULT NULL COMMENT '朝向',
  `area` decimal(10,2) DEFAULT NULL COMMENT '房间面积（㎡）',
  `has_toilet` tinyint(1) DEFAULT '1' COMMENT '是否有独立卫浴：0-无 1-有',
  `has_balcony` tinyint(1) DEFAULT '0' COMMENT '是否有阳台：0-无 1-有',
  `has_nurse_call` tinyint(1) DEFAULT '1' COMMENT '是否有床头呼叫器：0-无 1-有',
  `facility_json` varchar(1000) DEFAULT NULL COMMENT '适老设施（JSON：扶手/防滑地垫/护理床等）',
  `daily_price` decimal(10,2) DEFAULT '80.00' COMMENT '日单价（元）',
  `space_price_type` int DEFAULT '0' COMMENT '价格类型：0-普通价格 1-会员价格',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态 0-禁用 1-空闲 2-已预订 3-已满房 4-维修中 5-清洁中',
  `environment_images` varchar(2000) DEFAULT NULL COMMENT '环境图片（JSON数组）',
  `camera_device_id` varchar(145) DEFAULT NULL COMMENT '房间监控设备编号',
  `content` varchar(450) DEFAULT NULL COMMENT '房间说明',
  `remark` varchar(450) DEFAULT NULL COMMENT '备注',
  `sort_order` int DEFAULT '100' COMMENT '排序',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '删除标志：0-正常 1-已删除',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_room_no` (`floor_id`,`room_no`,`is_delete`),
  KEY `idx_building_floor` (`building_id`,`floor_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=239 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='房间表';
/*!40101 SET character_set_client = @saved_cs_client */;

