--
-- Table structure for table `e_care_settlement`
--

DROP TABLE IF EXISTS `e_care_settlement`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_care_settlement` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `settlement_no` varchar(50) NOT NULL COMMENT '结算单号',
  `checkin_id` bigint NOT NULL COMMENT '入住登记ID（e_care_checkin.id）',
  `resident_id` int NOT NULL COMMENT '长者ID（关联 e_resident.id）',
  `bed_fee` decimal(10,2) DEFAULT '0.00' COMMENT '床位费',
  `care_fee` decimal(10,2) DEFAULT '0.00' COMMENT '护理费',
  `meal_fee` decimal(10,2) DEFAULT '0.00' COMMENT '餐费',
  `service_fee` decimal(10,2) DEFAULT '0.00' COMMENT '增值服务费用',
  `other_fee` decimal(10,2) DEFAULT '0.00' COMMENT '其他费用',
  `subtotal` decimal(10,2) DEFAULT '0.00' COMMENT '费用小计',
  `discount` decimal(10,2) DEFAULT '0.00' COMMENT '优惠金额',
  `total_amount` decimal(10,2) DEFAULT '0.00' COMMENT '费用总计',
  `total_deposit` decimal(10,2) DEFAULT '0.00' COMMENT '已付押金',
  `final_amount` decimal(10,2) DEFAULT '0.00' COMMENT '应收/应退金额',
  `deposit_status` tinyint(1) DEFAULT '0' COMMENT '押金状态（0-未支付 1-已支付 2-已退还）',
  `deposit_payment` decimal(10,2) DEFAULT '0.00' COMMENT '押金支付金额',
  `deposit_refund_time` datetime DEFAULT NULL COMMENT '押金退还时间',
  `payment_method` varchar(20) DEFAULT NULL COMMENT '支付方式（CASH-现金 WECHAT-微信 ALIPAY-支付宝 CARD-银行卡 MEMBER_CARD-会员卡）',
  `actual_payment` decimal(10,2) DEFAULT '0.00' COMMENT '实收金额',
  `payment_remark` varchar(200) DEFAULT NULL COMMENT '支付备注',
  `status` tinyint(1) DEFAULT '0' COMMENT '状态（0-待结算 1-已结算 2-已退款）',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `is_delete` tinyint(1) DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_settlement_no` (`settlement_no`),
  KEY `idx_checkin_id` (`checkin_id`),
  KEY `idx_resident_id` (`resident_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=639 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='退住结算表';
/*!40101 SET character_set_client = @saved_cs_client */;

