DROP TABLE IF EXISTS `e_care_settlement_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_care_settlement_detail` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `settlement_id` bigint NOT NULL COMMENT '结算ID',
  `checkin_id` bigint NOT NULL COMMENT '入住登记ID（e_care_checkin.id）',
  `resident_name` varchar(50) NOT NULL COMMENT '长者姓名',
  `item_id` bigint DEFAULT NULL COMMENT '费用项ID',
  `item_name` varchar(100) NOT NULL COMMENT '费用项名称',
  `item_type` varchar(30) NOT NULL COMMENT '费用项类型',
  `charge_mode` tinyint(1) NOT NULL COMMENT '计费方式（0-按天 1-按次 2-固定 3-按重 4-按年 5-按月）',
  `unit_price` decimal(10,2) NOT NULL COMMENT '单价',
  `quantity` int NOT NULL COMMENT '数量',
  `days` int DEFAULT '1' COMMENT '天数',
  `subtotal` decimal(10,2) NOT NULL COMMENT '小计',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_delete` tinyint(1) DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`id`),
  KEY `idx_settlement_id` (`settlement_id`),
  KEY `idx_checkin_id` (`checkin_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1116 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='结算明细表';
