--
-- Table structure for table `e_gps_activity_statistics`
--

DROP TABLE IF EXISTS `e_gps_activity_statistics`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_gps_activity_statistics` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `device_id` bigint NOT NULL COMMENT '设备ID',
  `resident_id` bigint DEFAULT NULL COMMENT '长者ID',
  `guardian_id` bigint DEFAULT NULL COMMENT '家属ID',
  `stat_date` date NOT NULL COMMENT '统计日期',
  `total_distance` double DEFAULT '0' COMMENT '总移动距离（米）',
  `active_duration` int DEFAULT '0' COMMENT '活动时长（分钟）',
  `rest_duration` int DEFAULT '0' COMMENT '休息时长（分钟）',
  `max_speed` double DEFAULT NULL COMMENT '最高速度（km/h）',
  `avg_speed` double DEFAULT NULL COMMENT '平均速度（km/h）',
  `step_count` int DEFAULT '0' COMMENT '步数（估算）',
  `calorie_burn` double DEFAULT NULL COMMENT '消耗卡路里（估算）',
  `track_point_count` int DEFAULT '0' COMMENT '轨迹点数量',
  `fence_alarm_count` int DEFAULT '0' COMMENT '围栏报警次数',
  `create_at` datetime DEFAULT NULL COMMENT '创建时间',
  `update_at` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_device_date` (`device_id`,`stat_date`),
  KEY `idx_e_id` (`resident_id`),
  KEY `idx_owner_id` (`guardian_id`),
  KEY `idx_stat_date` (`stat_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='宠物活动统计表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `e_gps_activity_statistics`
--

LOCK TABLES `e_gps_activity_statistics` WRITE;
/*!40000 ALTER TABLE `e_gps_activity_statistics` DISABLE KEYS */;
/*!40000 ALTER TABLE `e_gps_activity_statistics` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `e_gps_device`
--

DROP TABLE IF EXISTS `e_gps_device`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_gps_device` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '设备ID',
  `device_code` varchar(100) NOT NULL COMMENT '设备编码',
  `device_name` varchar(145) NOT NULL COMMENT '设备名称',
  `resident_id` bigint DEFAULT NULL COMMENT '长者ID',
  `resident_name` varchar(64) DEFAULT NULL COMMENT '长者姓名',
  `guardian_id` bigint DEFAULT NULL COMMENT '家属ID',
  `guardian_name` varchar(64) DEFAULT NULL COMMENT '家属姓名',
  `guardian_phone` varchar(32) DEFAULT NULL COMMENT '家属电话',
  `boarding_id` bigint DEFAULT NULL COMMENT '寄养订单ID',
  `room_id` bigint DEFAULT NULL COMMENT '房间/笼位ID',
  `room_name` varchar(145) DEFAULT NULL COMMENT '房间名称',
  `device_type` varchar(50) DEFAULT 'GPS_TRACKER' COMMENT '设备类型：GPS_TRACKER-GPS跟踪器',
  `protocol` varchar(20) DEFAULT 'mqtt' COMMENT '协议类型',
  `sim_card_no` varchar(50) DEFAULT NULL COMMENT 'SIM卡号',
  `imei` varchar(50) DEFAULT NULL COMMENT 'IMEI码',
