--
-- Table structure for table `e_gps_fence_camera_link`
--

DROP TABLE IF EXISTS `e_gps_fence_camera_link`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_gps_fence_camera_link` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `fence_id` bigint NOT NULL COMMENT '围栏ID（e_gps_electronic_fence.id）',
  `fence_name` varchar(145) DEFAULT NULL COMMENT '围栏名称',
  `camera_device_id` bigint NOT NULL COMMENT '摄像头设备ID（e_camera_device.id）',
  `camera_device_name` varchar(145) DEFAULT NULL COMMENT '摄像头名称',
  `trigger_action` varchar(50) DEFAULT 'SNAPSHOT' COMMENT '触发动作：SNAPSHOT-截图 RECORD-录像 BOTH-截图+录像',
  `record_duration` int DEFAULT '30' COMMENT '录像时长（秒）',
  `snapshot_count` int DEFAULT '1' COMMENT '截图数量',
  `alarm_level_override` varchar(45) DEFAULT NULL COMMENT '覆盖报警等级（为空则使用围栏原等级）',
  `is_active` int DEFAULT '1' COMMENT '是否启用：0-禁用 1-启用',
  `tenant_id` bigint DEFAULT NULL COMMENT '租户ID',
  `tenant_name` varchar(100) DEFAULT NULL COMMENT '租户名称',
  `is_delete` int DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(100) DEFAULT NULL COMMENT '创建者',
  `create_at` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(100) DEFAULT NULL COMMENT '更新者',
  `update_at` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_fence_camera` (`fence_id`,`camera_device_id`,`is_delete`),
  KEY `idx_fence_id` (`fence_id`),
  KEY `idx_camera_device_id` (`camera_device_id`),
  KEY `idx_is_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='围栏-摄像头联动配置表';
/*!40101 SET character_set_client = @saved_cs_client */;

