--
-- Table structure for table `e_gps_track`
--

DROP TABLE IF EXISTS `e_gps_track`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_gps_track` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `device_id` bigint NOT NULL COMMENT '设备ID',
  `device_code` varchar(100) NOT NULL COMMENT '设备编码',
  `resident_id` bigint DEFAULT NULL COMMENT '长者ID',
  `resident_name` varchar(64) DEFAULT NULL COMMENT '长者姓名',
  `guardian_id` bigint DEFAULT NULL COMMENT '家属ID',
  `guardian_name` varchar(64) DEFAULT NULL COMMENT '家属姓名',
  `boarding_id` bigint DEFAULT NULL COMMENT '寄养订单ID',
  `room_id` bigint DEFAULT NULL COMMENT '房间/笼位ID',
  `latitude` double NOT NULL COMMENT '纬度',
  `longitude` double NOT NULL COMMENT '经度',
  `altitude` double DEFAULT NULL COMMENT '海拔高度（米）',
  `speed` double DEFAULT NULL COMMENT '速度（km/h）',
  `direction` double DEFAULT NULL COMMENT '方向角度（0-360）',
  `accuracy` double DEFAULT NULL COMMENT '定位精度（米）',
  `location_type` varchar(20) DEFAULT 'GPS' COMMENT '定位类型：GPS-卫星定位 BASE-基站定位 WIFI-WIFI定位',
  `address` varchar(500) DEFAULT NULL COMMENT '地址信息',
  `province` varchar(50) DEFAULT NULL COMMENT '省份',
  `city` varchar(50) DEFAULT NULL COMMENT '城市',
  `district` varchar(50) DEFAULT NULL COMMENT '区域',
  `track_time` datetime NOT NULL COMMENT '轨迹时间',
  `is_valid` int DEFAULT '1' COMMENT '是否有效：0-无效 1-有效',
  `is_fence_alarm` int DEFAULT '0' COMMENT '是否触发围栏报警：0-否 1-是',
  `camera_device_id` bigint DEFAULT NULL COMMENT '关联最近摄像头设备ID',
  `camera_snapshot_id` bigint DEFAULT NULL COMMENT '关联截图ID',
  `camera_record_id` bigint DEFAULT NULL COMMENT '关联录像ID',
  `battery_level` int DEFAULT NULL COMMENT '设备电量（%）',
  `signal_strength` int DEFAULT NULL COMMENT '信号强度',
  `create_at` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_device_id` (`device_id`),
  KEY `idx_e_id` (`resident_id`),
  KEY `idx_owner_id` (`guardian_id`),
  KEY `idx_track_time` (`track_time`),
  KEY `idx_location` (`latitude`,`longitude`),
  KEY `idx_fence_alarm` (`is_fence_alarm`),
  KEY `idx_boarding_id` (`boarding_id`),
  KEY `idx_camera_device_id` (`camera_device_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='宠物GPS轨迹表';
/*!40101 SET character_set_client = @saved_cs_client */;

