--
-- Table structure for table `e_ledger_elder`
--

DROP TABLE IF EXISTS `e_ledger_elder`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_ledger_elder` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '老人ID',
  `resident_id` bigint DEFAULT NULL COMMENT '关联在住长者ID(e_resident.id),居家老人为空;机构同步档案时回填',
  `elder_source` tinyint DEFAULT '1' COMMENT '档案来源：1社区居家登记 2机构在住长者同步',
  `elder_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '台账编号(LT+区域+流水,与在住编号R区分)',
  `name` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '老人姓名',
  `id_card` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证号',
  `gender` tinyint DEFAULT '0' COMMENT '性别：0未知 1男 2女(对齐e_store_employee/sys_user_sex)',
  `birthday` date DEFAULT NULL COMMENT '出生日期',
  `nation` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '民族',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '老人联系电话',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '现居住地址',
  `household_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '户籍地址',
  `elder_types` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '老人类型编码集(逗号分隔,字典ledger_elder_type)：1特困 2低保 3独居 4空巢 5留守 6残疾',
  `care_level` tinyint DEFAULT '1' COMMENT '照料等级(对齐e_resident.care_level/CARE_LEVEL_OPTIONS)：1自理 2半自理 3失能',
  `self_care_ability` tinyint DEFAULT NULL COMMENT '自理能力(对齐e_resident)：1完全自理 2部分自理 3不能自理',
  `cognitive_status` tinyint DEFAULT NULL COMMENT '认知状况(对齐e_resident)：1正常 2疑似障碍 3确诊障碍',
  `adl_score` int DEFAULT NULL COMMENT 'ADL日常生活能力评分(0-100,对齐e_resident)',
  `fall_risk` tinyint DEFAULT NULL COMMENT '跌倒风险(对齐e_resident)：1低 2中 3高',
  `chronic_disease` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '基础慢病',
  `allergy` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '过敏史',
  `medicine_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '长期用药情况',
  `health_status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '总体健康状况',
  `helper_employee_id` bigint DEFAULT NULL COMMENT '帮扶责任人ID(e_store_employee.id)',
  `helper_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '帮扶责任人姓名(冗余)',
  `area_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '归属片区',
  `risk_level` tinyint DEFAULT '1' COMMENT '风险等级(字典ledger_risk_level)：1低/一般 2关注 3高',
  `archive_images` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '档案附件URL集(身份证照片/评估表/体检单,逗号分隔)',
  `state` tinyint NOT NULL DEFAULT '1' COMMENT '档案状态：0注销 1正常 2停用',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0否 1是',
  PRIMARY KEY (`id`),
  KEY `idx_resident_id` (`resident_id`),
  KEY `idx_id_card` (`id_card`),
  KEY `idx_name` (`name`),
  KEY `idx_risk_level` (`risk_level`),
  KEY `idx_care_level` (`care_level`),
  KEY `idx_state` (`state`),
  KEY `idx_create_at` (`create_at`),
  KEY `idx_store_state_risk` (`state`,`risk_level`)
) ENGINE=InnoDB AUTO_INCREMENT=6025 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='智慧台账-老人档案(居家上门服务主档,可选关联e_resident)';
/*!40101 SET character_set_client = @saved_cs_client */;

