  PRIMARY KEY (`id`),
  KEY `idx_elder_id` (`elder_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6237 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='智慧台账-老人紧急联系人';
