--
-- Table structure for table `e_ledger_order_log`
--

DROP TABLE IF EXISTS `e_ledger_order_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_ledger_order_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `order_kind` tinyint NOT NULL COMMENT '工单类别：1探访工单 2巡访工单',
  `order_id` bigint NOT NULL COMMENT '工单ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单编号(冗余便于台账检索)',
  `action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作(字典ledger_order_action)：assign分派 transfer转派 revoke撤回 sign签到 start开始 rectify处置 review复查 close结案 cancel取消 delay延期 finish完成 reject驳回 revisit重访',
  `from_status` tinyint DEFAULT NULL COMMENT '流转前状态',
  `to_status` tinyint DEFAULT NULL COMMENT '流转后状态',
  `from_employee_id` bigint DEFAULT NULL COMMENT '原办理人(e_store_employee.id)',
  `to_employee_id` bigint DEFAULT NULL COMMENT '新办理人(转派/分派目标,e_store_employee.id)',
  `content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作说明/驳回原因等',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '操作人',
  `create_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`),
  KEY `idx_order` (`order_kind`,`order_id`),
  KEY `idx_create_at` (`create_at`)
) ENGINE=InnoDB AUTO_INCREMENT=8259 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工单流转日志';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `e_ledger_order_log`
--

LOCK TABLES `e_ledger_order_log` WRITE;
/*!40000 ALTER TABLE `e_ledger_order_log` DISABLE KEYS */;
