--
-- Table structure for table `e_ledger_patrol_order`
--

DROP TABLE IF EXISTS `e_ledger_patrol_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_ledger_patrol_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '巡访工单ID',
  `elder_id` bigint DEFAULT NULL COMMENT '关联老人ID(e_ledger_elder.id,院内巡访可空)',
  `elder_name` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '老人姓名(冗余)',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工单编号(XF+yyyyMMdd+4位流水)',
  `patrol_type` tinyint NOT NULL DEFAULT '1' COMMENT '巡访类型(字典ledger_patrol_type)：1日常安全 2高危专项 3投诉巡访 4隐患复查',
  `risk_level` tinyint NOT NULL DEFAULT '1' COMMENT '本次巡访风险等级(字典ledger_risk_level)：1一般 2关注 3高风险',
  `plan_patrol_time` datetime DEFAULT NULL COMMENT '计划巡访时间',
  `employee_id` bigint DEFAULT NULL COMMENT '指派巡访员(e_store_employee.id)',
  `employee_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '巡访员姓名(冗余)',
  `order_status` tinyint NOT NULL DEFAULT '1' COMMENT '状态(字典ledger_patrol_order_status)：1待分派 2待巡访 3处置中 4待复查 5已结案 6取消',
  `delay_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '延期原因',
  `delay_time` datetime DEFAULT NULL COMMENT '延期登记时间',
  `delay_count` int DEFAULT '0' COMMENT '累计延期次数',
  `patrol_place` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '巡访地点(院落/楼栋/老人住址)',
  `sign_time` datetime DEFAULT NULL COMMENT '到场签到时间',
  `real_patrol_time` datetime DEFAULT NULL COMMENT '实际巡访时间',
  `patrol_images` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '现场拍照URL集(逗号分隔)',
  `dispose_opinion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '初步处置意见',
  `rectify_deadline` datetime DEFAULT NULL COMMENT '整改期限',
  `rectify_employee_id` bigint DEFAULT NULL COMMENT '整改责任人(e_store_employee.id)',
  `rectify_employee_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '整改责任人姓名(冗余)',
  `review_time` datetime DEFAULT NULL COMMENT '复查完成时间',
  `review_result` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '复查结论',
  `review_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '复查人(登录账号)',
  `source_order_id` bigint DEFAULT NULL COMMENT '来源工单ID(隐患复查时指向原巡访单)',
  `source_type` tinyint DEFAULT '1' COMMENT '来源：1计划生成 2人工上报 3风险预警触发',
  `plan_id` bigint DEFAULT NULL COMMENT '巡访计划ID(e_ledger_visit_plan.id,type=2计划)',
  `cancel_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '取消原因',
  `cancel_time` datetime DEFAULT NULL COMMENT '取消时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0否 1是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_elder_id` (`elder_id`),
  KEY `idx_employee_id` (`employee_id`),
  KEY `idx_order_status` (`order_status`),
  KEY `idx_risk_level` (`risk_level`),
  KEY `idx_plan_patrol_time` (`plan_patrol_time`),
  KEY `idx_store_status_time` (`order_status`,`plan_patrol_time`),
  KEY `idx_source_order_id` (`source_order_id`),
  KEY `idx_rectify_employee_id` (`rectify_employee_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7623 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='巡访工单(安全巡查/隐患处置)';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `e_ledger_patrol_order`
--

