--
-- Table structure for table `e_ledger_patrol_risk_item`
--

DROP TABLE IF EXISTS `e_ledger_patrol_risk_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_ledger_patrol_risk_item` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `order_id` bigint NOT NULL COMMENT '巡访工单ID(e_ledger_patrol_order.id)',
  `risk_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '隐患项编码(字典ledger_risk_item)：1用电 2用火 3用气 4防滑 5防坠床 6食品药品 7其他',
  `risk_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '隐患详细描述',
  `risk_level` tinyint DEFAULT '1' COMMENT '隐患等级：1一般 2关注 3高风险',
  `handle_suggest` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '整改建议',
  `item_images` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '隐患现场照片URL集(逗号分隔)',
  `is_fixed` tinyint(1) DEFAULT '0' COMMENT '是否已整改：0否 1是',
  `fix_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '整改说明',
  `fix_images` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '整改后照片URL集(逗号分隔)',
  `fix_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '整改人(登录账号/姓名)',
  `fix_time` datetime DEFAULT NULL COMMENT '整改完成时间',
  `create_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0否 1是',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_is_fixed` (`is_fixed`),
  KEY `idx_order_fixed` (`order_id`,`is_fixed`)
) ENGINE=InnoDB AUTO_INCREMENT=7930 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='巡访隐患明细';
/*!40101 SET character_set_client = @saved_cs_client */;

