CREATE TABLE `e_ledger_revisit` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `order_kind` tinyint NOT NULL DEFAULT '1' COMMENT '被回访工单类别：1探访工单 2巡访工单',
  `order_id` bigint NOT NULL COMMENT '被回访工单ID',
  `elder_id` bigint DEFAULT NULL COMMENT '老人ID',
  `revisit_time` datetime DEFAULT NULL COMMENT '回访时间',
  `revisit_employee_id` bigint DEFAULT NULL COMMENT '回访人(e_store_employee.id)',
  `satisfaction` tinyint DEFAULT NULL COMMENT '满意度：1满意 2一般 3不满意',
  `is_qualified` tinyint(1) DEFAULT '1' COMMENT '回访是否合格：0不合格(触发重访工单) 1合格',
  `revisit_order_id` bigint DEFAULT NULL COMMENT '不合格时生成的重访工单ID',
  `content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '回访记录',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0否 1是',
  PRIMARY KEY (`id`),
  KEY `idx_order` (`order_kind`,`order_id`),
  KEY `idx_elder_id` (`elder_id`)
) ENGINE=InnoDB AUTO_INCREMENT=8514 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工单回访记录';
