/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_ledger_visit_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '工单ID',
  `elder_id` bigint NOT NULL COMMENT '老人ID(e_ledger_elder.id)',
  `elder_name` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '老人姓名(冗余便于列表直显)',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工单编号(TF+yyyyMMdd+4位流水)',
  `visit_type` tinyint NOT NULL DEFAULT '1' COMMENT '探访类型(字典ledger_visit_type)：1常规关爱 2需求评估 3服务跟进 4回访重访',
  `plan_visit_time` datetime DEFAULT NULL COMMENT '计划探访时间',
  `employee_id` bigint DEFAULT NULL COMMENT '指派巡访员(e_store_employee.id),空为待分配',
  `employee_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '巡访员姓名(冗余)',
  `order_status` tinyint NOT NULL DEFAULT '1' COMMENT '状态(字典ledger_visit_order_status)：1待分配 2待上门 3已完成 4延期 5取消 6重访',
  `sign_time` datetime DEFAULT NULL COMMENT '上门签到时间',
  `sign_location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签到定位地址',
  `visit_start_time` datetime DEFAULT NULL COMMENT '探访开始时间',
  `visit_end_time` datetime DEFAULT NULL COMMENT '探访结束时间',
  `source_type` tinyint DEFAULT '1' COMMENT '来源：1计划生成 2人工新建',
  `plan_id` bigint DEFAULT NULL COMMENT '探访计划ID(e_ledger_visit_plan.id,计划生成时回填)',
  `delay_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '延期原因',
  `cancel_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '取消原因',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0否 1是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_elder_id` (`elder_id`),
  KEY `idx_employee_id` (`employee_id`),
  KEY `idx_order_status` (`order_status`),
  KEY `idx_plan_visit_time` (`plan_visit_time`),
  KEY `idx_store_status_time` (`order_status`,`plan_visit_time`)
) ENGINE=InnoDB AUTO_INCREMENT=7031 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='探访工单(关爱探访)';
/*!40101 SET character_set_client = @saved_cs_client */;

