--
-- Table structure for table `e_ledger_visit_plan`
--

DROP TABLE IF EXISTS `e_ledger_visit_plan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_ledger_visit_plan` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '计划ID',
  `plan_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '计划名称(如:独居老人每月探访)',
  `plan_type` tinyint NOT NULL DEFAULT '1' COMMENT '计划类型：1探访计划 2巡访计划',
  `elder_types` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '针对老人类型集(逗号分隔,空为全部)',
  `care_levels` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '针对照料等级集(逗号分隔,空为全部)',
  `risk_level` tinyint DEFAULT NULL COMMENT '针对风险等级(空为全部)：1低 2中 3高',
  `frequency_type` tinyint NOT NULL DEFAULT '1' COMMENT '频次周期：1每天 2每周 3每月',
  `frequency_times` int NOT NULL DEFAULT '1' COMMENT '每周期生成次数(如独居每月2次=2)',
  `default_visit_type` tinyint DEFAULT '1' COMMENT '生成工单的探访/巡访类型默认值',
