DROP TABLE IF EXISTS `e_ledger_visit_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_ledger_visit_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `order_id` bigint NOT NULL COMMENT '探访工单ID(e_ledger_visit_order.id,一单一记录)',
  `elder_id` bigint NOT NULL COMMENT '老人ID',
  `elder_name` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '老人姓名(冗余)',
  `real_visit_time` datetime DEFAULT NULL COMMENT '实际探访时间',
  `accompany_person` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '陪同人员',
  `mental_status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '精神状态',
  `diet_status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '饮食情况',
  `sleep_status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '睡眠情况',
  `move_status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '行动情况',
  `blood_pressure` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '血压(如 130/85)',
  `blood_sugar` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '血糖',
  `medicine_compliance` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用药依从性',
  `demand_info` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务需求集(字典ledger_service_item编码,逗号分隔)：1生活照料 2助餐 3助洁 4助医 5心理疏导',
  `demand_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '需求详细描述',
  `home_env_risk` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '居家环境风险(防滑/用电用气/防坠床等)',
  `service_suggest` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '服务建议',
  `next_visit_time` datetime DEFAULT NULL COMMENT '建议下次探访时间',
  `visit_images` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '现场图片URL集(逗号分隔)',
  `sign_img_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '老人/家属电子签名图URL',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '其他说明',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '填写人',
  `create_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0否 1是',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_elder_id` (`elder_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7317 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='上门探访记录(依附探访工单)';
