DROP TABLE IF EXISTS `e_meals_menus`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_meals_menus` (
  `id` int NOT NULL AUTO_INCREMENT,
  `menu_date` date DEFAULT NULL COMMENT '菜单日期',
  `meal_type` tinyint NOT NULL COMMENT '餐次类型：1早餐，2午餐，3晚餐，4加餐',
  `dish_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜名',
  `dish_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '菜品图片',
  `dish_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '菜品描述',
  `nutrition_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '营养信息',
  `suitable_for` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '适宜人群',
  `contraindicated_for` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '禁忌人群',
  `creator_id` int DEFAULT NULL COMMENT '创建人ID',
  `status` tinyint DEFAULT '1' COMMENT '状态：1正常，0停用',
  `is_delete` tinyint DEFAULT '0' COMMENT '是否删除：1是，0否',
  `create_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4057 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='餐饮菜单表';
