DROP TABLE IF EXISTS `e_meals_package`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_meals_package` (
  `id` int NOT NULL AUTO_INCREMENT,
  `package_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '套餐名称',
  `meal_type` tinyint NOT NULL COMMENT '餐次类型：1早餐，2午餐，3晚餐，4加餐',
  `package_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '套餐图片',
  `menu_ids` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '包含的菜单ID集合(逗号分隔)',
  `price` decimal(10,2) DEFAULT NULL COMMENT '套餐价格',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '套餐描述',
  `creator_id` int DEFAULT NULL COMMENT '创建人ID',
  `status` tinyint DEFAULT '1' COMMENT '状态：1正常，0停用',
  `is_delete` tinyint DEFAULT '0' COMMENT '是否删除：1是，0否',
  `create_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=509 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='餐饮套餐表';
/*!40101 SET character_set_client = @saved_cs_client */;

