DROP TABLE IF EXISTS `e_meals_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_meals_record` (
  `id` int NOT NULL AUTO_INCREMENT,
  `resident_id` int DEFAULT NULL COMMENT '老人ID(专人专餐单人不为空)',
  `meal_target_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '所有人' COMMENT '用餐对象类型：所有人，专人专餐',
  `resident_ids` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '专人专餐老人ID集合(逗号分隔)',
  `package_id` int DEFAULT NULL COMMENT '关联套餐ID',
  `package_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '套餐名称',
  `meal_date` date NOT NULL COMMENT '用餐日期',
  `meal_type` tinyint NOT NULL COMMENT '餐次类型：1早餐，2午餐，3晚餐，4加餐',
  `dish_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '菜名',
  `quantity` decimal(5,2) DEFAULT NULL COMMENT '份量',
  `satisfaction_level` enum('很满意','满意','一般','不满意') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '满意度',
  `feedback` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '反馈意见',
  `meal_photos` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '照片记录(逗号分隔)',
  `served_by` int DEFAULT NULL COMMENT '服务人员ID',
  `served_time` time DEFAULT NULL COMMENT '供餐时间',
  `status` tinyint DEFAULT '1' COMMENT '状态：1正常，0取消',
  `is_delete` tinyint DEFAULT '0' COMMENT '是否删除：1是，0否',
  `create_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9113 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='餐饮记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

