--
-- Table structure for table `e_resident`
--

DROP TABLE IF EXISTS `e_resident`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_resident` (
  `id` int NOT NULL AUTO_INCREMENT,
  `resident_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '老人编号',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '姓名',
  `gender` enum('男','女') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '性别',
  `birth_date` date DEFAULT NULL COMMENT '出生日期',
  `id_card` varchar(28) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证号',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `address` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '家庭住址',
  `emergency_contact` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '紧急联系人',
  `emergency_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '紧急联系电话',
  `admission_date` date DEFAULT NULL COMMENT '入住日期',
  `check_in_time` datetime DEFAULT NULL COMMENT '入住时间',
  `check_out_time` datetime DEFAULT NULL COMMENT '离店时间(空=在住)',
  `room_id` bigint DEFAULT NULL COMMENT '房间ID（关联 e_store_room.id）',
  `bed_id` bigint DEFAULT NULL COMMENT '床位ID（关联 e_store_bed.id）',
  `check_in_status` tinyint DEFAULT '0' COMMENT '入住状态：0未入住 1在住 2已退住',
  `room_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '入住房间号',
  `bed_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '床铺号',
  `care_level` tinyint DEFAULT '1' COMMENT '护理等级：1自理，2半自理，3失能',
  `health_status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '健康状况',
  `hobbies` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '兴趣爱好',
  `remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `status` tinyint DEFAULT '1' COMMENT '状态：0-退住 1-在住 2-预约 3-请假外出',
  `is_delete` tinyint DEFAULT '0' COMMENT '是否删除：1是，0否',
  `create_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `nation` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '民族',
  `native_place` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '籍贯',
  `marital_status` tinyint DEFAULT NULL COMMENT '婚姻状况:1未婚 2已婚 3丧偶 4离异 5再婚',
  `education` tinyint DEFAULT NULL COMMENT '文化程度:1文盲 2小学 3初中 4高中/中专 5大专 6本科及以上',
  `political_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '政治面貌',
  `religion` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '宗教信仰',
  `blood_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '血型',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '长者照片URL',
  `height` int DEFAULT NULL COMMENT '身高(cm)',
  `weight` int DEFAULT NULL COMMENT '体重(kg)',
  `self_care_ability` tinyint DEFAULT NULL COMMENT '自理能力:1完全自理 2部分自理 3不能自理',
  `cognitive_status` tinyint DEFAULT NULL COMMENT '认知状况:1正常 2疑似障碍 3确诊障碍',
  `adl_score` int DEFAULT NULL COMMENT 'ADL日常生活能力评分(0-100)',
  `fall_risk` tinyint DEFAULT NULL COMMENT '跌倒风险:1低 2中 3高',
  `chronic_disease` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '慢性病',
  `medical_history` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '既往病史',
  `family_history` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '家族病史',
  `allergy_history` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '过敏史',
  `medication` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用药情况',
  `check_in_type` tinyint DEFAULT NULL COMMENT '入住性质:1长期 2短期 3日间照料 4试住',
  `check_in_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '入住原因',
  `nursing_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '护理等级',
  `diet_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '膳食类型',
  `special_diet` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '特殊饮食',
  `medical_insurance_type` tinyint DEFAULT NULL COMMENT '医保类型:1城镇职工 2城乡居民 3新农合 4自费',
  `medical_insurance_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '医保卡号',
  `social_security_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '社保卡号',
  `income_source` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '经济来源',
  `guarantor` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '担保人',
  `guarantor_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '担保人电话',
  `check_out_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '离店原因',
  `settlement_status` tinyint DEFAULT NULL COMMENT '结算状态:0未结算 1已结算',
  PRIMARY KEY (`id`),
  UNIQUE KEY `resident_no` (`resident_no`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='老人基本信息表';
