--
-- Table structure for table `e_resident_card`
--

DROP TABLE IF EXISTS `e_resident_card`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_resident_card` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `card_no` varchar(30) NOT NULL COMMENT '会员卡号，唯一，如：VIP20240001',
  `resident_id` bigint NOT NULL COMMENT '长者ID，关联 e_resident.id',
  `resident_name` varchar(50) NOT NULL COMMENT '长者姓名（冗余，提升查询性能）',
  `resident_phone` varchar(20) DEFAULT NULL COMMENT '长者/家属手机号（冗余）',
  `package_id` bigint DEFAULT NULL COMMENT '开卡套餐ID，关联 member_card_package.id',
  `card_level` int NOT NULL DEFAULT '0' COMMENT '会员等级: 0-普通卡 1-银卡 2-金卡 3-钻石卡',
  `balance` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '现金余额（消费/充值变动）',
  `gift_balance` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '赠送余额（开卡/充值赠送，优先消费）',
  `total_recharge` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '累计充值金额',
  `total_consume` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '累计消费金额',
  `open_date` date DEFAULT NULL COMMENT '开卡日期',
  `expire_date` date DEFAULT NULL COMMENT '有效期截止日（NULL表示永久）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：0-注销 1-正常 2-挂失',
  `pay_method` varchar(20) DEFAULT NULL COMMENT '开卡支付方式：wechat alipay cash card',
  `open_amount` decimal(10,2) DEFAULT '0.00' COMMENT '开卡实付金额',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-正常 1-已删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_card_no` (`card_no`),
  KEY `idx_resident_id` (`resident_id`),
  KEY `idx_card_level` (`card_level`),
  KEY `idx_status` (`status`),
  KEY `idx_open_date` (`open_date`)
) ENGINE=InnoDB AUTO_INCREMENT=815 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='长者会员卡表';
/*!40101 SET character_set_client = @saved_cs_client */;

