DROP TABLE IF EXISTS `e_resident_card_package`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_resident_card_package` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(100) NOT NULL COMMENT '套餐名称，如：金卡充值套餐A',
  `card_level` int NOT NULL DEFAULT '0' COMMENT '会员等级: 0-普通卡 1-银卡 2-金卡 3-钻石卡',
  `original_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '原始金额（元）',
  `discount_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '优惠金额（元）',
  `actual_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '实际收费金额 = original - discount',
  `gift_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '赠送金额（入账到赠送余额）',
  `description` varchar(500) DEFAULT NULL COMMENT '套餐说明，如：有效期12个月、不可退换等',
  `is_hot` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否热销推荐：0-否 1-是',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：0-禁用 1-启用',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序（升序）',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-正常 1-已删除',
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
  KEY `idx_card_level` (`card_level`),
  KEY `idx_sort_order` (`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='会员卡套餐表（长者/家属储值）';
/*!40101 SET character_set_client = @saved_cs_client */;

