DROP TABLE IF EXISTS `e_resident_card_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_resident_card_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `trade_no` varchar(40) NOT NULL COMMENT '交易流水号，唯一，如：TRD20260315001',
  `card_id` bigint NOT NULL COMMENT '会员卡ID，关联 e_resident_card.id',
  `card_no` varchar(30) DEFAULT NULL COMMENT '会员卡号（冗余）',
  `resident_id` bigint DEFAULT NULL COMMENT '长者ID（冗余，关联 e_resident.id）',
  `resident_name` varchar(50) DEFAULT NULL COMMENT '长者姓名（冗余）',
  `trade_type` varchar(20) NOT NULL COMMENT '交易类型：consume-消费 recharge-充值 refund-退款 open-开卡',
  `amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '交易金额（充值/消费的正向金额）',
  `gift_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '本次赠送金额（充值赠送入账）',
  `before_balance` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '现金余额（交易前）',
  `after_balance` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '现金余额（交易后）',
  `before_gift` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '赠送余额（交易前）',
  `after_gift` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '赠送余额（交易后）',
  `service_type` varchar(20) DEFAULT NULL COMMENT '服务类型：care-住养 care_svc-照护服务 rehab-康复 med-医疗 day-日托（消费时填写）',
  `checkin_id` bigint DEFAULT NULL COMMENT '关联入住登记单ID（住养消费时填写）',
  `settlement_id` bigint DEFAULT NULL COMMENT '关联结算单ID（结算消费时填写）',
  `use_gift` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否使用赠送余额：0-否 1-是',
  `pay_method` varchar(20) DEFAULT NULL COMMENT '支付方式：wechat alipay cash card',
  `trade_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '交易时间',
  `operator` varchar(50) DEFAULT NULL COMMENT '操作人（前台/系统）',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
