DROP TABLE IF EXISTS `e_wms_customer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_wms_customer` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `customer_name` varchar(50) NOT NULL COMMENT '客户姓名',
  `customer_phone` varchar(20) NOT NULL COMMENT '联系电话',
  `customer_type` varchar(20) DEFAULT 'WALK_IN' COMMENT '客户类型（WALK_IN-散客 MEMBER-会员 e_OWNER-宠物主人）',
  `guardian_id` bigint DEFAULT NULL COMMENT '关联家属ID',
  `member_level` varchar(20) DEFAULT NULL COMMENT '会员等级',
  `member_balance` decimal(10,2) DEFAULT '0.00' COMMENT '会员余额',
  `total_consumption` decimal(12,2) DEFAULT '0.00' COMMENT '累计消费金额',
  `total_orders` int DEFAULT '0' COMMENT '累计订单数',
  `last_purchase_date` date DEFAULT NULL COMMENT '最后购买日期',
  `address` varchar(200) DEFAULT NULL COMMENT '地址',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态（0-禁用 1-启用）',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `is_delete` tinyint(1) DEFAULT '0' COMMENT '删除标志',
  `kind` int DEFAULT '0' COMMENT '0 客户 1 供应商',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_customer_phone` (`customer_phone`),
  KEY `idx_customer_type` (`customer_type`),
  KEY `idx_owner_id` (`guardian_id`),
  KEY `idx_member_level` (`member_level`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='客户表（商品购买客户）';
/*!40101 SET character_set_client = @saved_cs_client */;

