DROP TABLE IF EXISTS `e_wms_product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_wms_product` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `product_name` varchar(100) NOT NULL COMMENT '商品名称',
  `brand_id` bigint DEFAULT NULL COMMENT '品牌ID',
  `category_id` bigint NOT NULL COMMENT '分类ID',
  `barcode` varchar(50) DEFAULT NULL COMMENT '条形码',
  `unit` varchar(20) NOT NULL COMMENT '单位（个/袋/瓶/盒）',
  `product_type` varchar(20) NOT NULL COMMENT '商品类型（FOOD-食品 SUPPLY-用品 MEDICINE-药品 TOY-玩具 SNACK-零食）',
  `market_price` decimal(10,2) DEFAULT NULL COMMENT '市场价',
  `description` text COMMENT '商品描述',
  `images` varchar(1000) DEFAULT NULL COMMENT '商品图片（多张逗号分隔）',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态（0-下架 1-上架）',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `is_delete` tinyint(1) DEFAULT '0' COMMENT '删除标志',
  `logo` varchar(450) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_brand_id` (`brand_id`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_barcode` (`barcode`),
  KEY `idx_product_type` (`product_type`)
) ENGINE=InnoDB AUTO_INCREMENT=123 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品主表';
