--
-- Table structure for table `e_wms_stock_log`
--

DROP TABLE IF EXISTS `e_wms_stock_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `e_wms_stock_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `sku_id` bigint NOT NULL COMMENT 'SKU ID',
  `batch_id` bigint DEFAULT NULL COMMENT '批次ID',
  `change_type` varchar(20) NOT NULL COMMENT '变动类型（PURCHASE-进货 SALES-出货 RETURN-退货 ADJUST-调整 EXPIRE-过期）',
  `change_quantity` int NOT NULL COMMENT '变动数量（正数入库，负数出库）',
  `before_stock` int NOT NULL COMMENT '变动前库存',
  `after_stock` int NOT NULL COMMENT '变动后库存',
  `related_order_no` varchar(50) DEFAULT NULL COMMENT '关联单号',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `is_delete` int DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_sku_id` (`sku_id`),
  KEY `idx_batch_id` (`batch_id`),
  KEY `idx_change_type` (`change_type`),
  KEY `idx_create_at` (`create_at`)
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='库存变动记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

