CREATE TABLE `sys_oss` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `oss_id` varchar(300) DEFAULT NULL COMMENT '模型名称',
  `url` varchar(455) DEFAULT NULL COMMENT '模型描述',
  `name` varchar(255) DEFAULT NULL COMMENT '请求地址',
  `file_size` int DEFAULT NULL COMMENT '文本块大小',
  `is_delete` int DEFAULT '0' COMMENT '删除标志：0-存在 1-删除',
  `create_by` bigint DEFAULT NULL COMMENT '创建者',
  `create_at` datetime DEFAULT NULL COMMENT '创建时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `prefix` varchar(45) DEFAULT NULL,
  `oss_type` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='oss管理';
